<!-- eslint-disable vue/no-v-html -- the SVG is generated by our own code from palette colours, never from user input -->
<template>
    <span
        :role="decorative ? undefined : 'img'"
        :aria-label="decorative ? undefined : t(`settings.style.names.${styleId}`)"
        :aria-hidden="decorative ? 'true' : undefined"
        :data-testid="`style-icon-${styleId}`"
        class="style-icon"
        :style="{ width: `${size}px`, height: `${size}px` }"
        v-html="svg"
    />
</template>

<script setup lang="ts">
import { computed, useId } from "vue";
import { useI18n } from "vue-i18n";
import type { Palette } from "@/theme/palettes";
import { styleIconSvg } from "@/theme/styleIcons";
import type { StyleId } from "@/theme/themeIds";

const props = defineProps<{
    styleId: StyleId;
    palette: Palette;
    size: number;
    /** Hides the icon from screen readers where the style's name is written beside it, so it is not read twice. */
    decorative?: boolean;
}>();

const { t } = useI18n();

// An icon with ids (cyberpunk's glow) must not share them with the page's other icons
const idSuffix = useId().replace(/\W/g, "");
const svg = computed(() => styleIconSvg(props.styleId, props.palette, idSuffix));
</script>

<style scoped>
.style-icon {
    display: block;
    flex-shrink: 0;
    overflow: hidden;
    border-radius: 24%;
}

.style-icon :deep(svg) {
    display: block;
    width: 100%;
    height: 100%;
}
</style>
